import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address recipient) public {
        // Exclude precompiles and the test contract itself to avoid interference
        vm.assume(recipient != address(this) && recipient != address(0) &&
                  recipient.code.length == 0 && recipient != address(c));

        // Deploy a re-entrant attacker and fund the contract
        ReEntrantAttacker attacker = new ReEntrantAttacker(c);
        vm.deal(address(c), 1 ether);

        // Use the attacker's address as the recipient
        attacker.attack();

        // After the attack, the recipient's claimedBonus must be true and rewardsForA must be 0
        bool claimed = c.claimedBonus(address(attacker));
        // rewardsForA is private, but the invariant is observable via the outcome of a second bonus attempt
        // We assert that the re-entrant call did NOT leave rewardsForA > 0 by checking that a second call fails
        bool secondCallReverts;
        vm.prank(address(this));
        try c.getFirstWithdrawalBonus(address(attacker)) {
            secondCallReverts = false;
        } catch {
            secondCallReverts = true;
        }
        // The reference guarantees: claimed is true AND secondCallReverts (because rewardsForA == 0 and claimedBonus == true, so the require fails)
        // The bug: claimed is true, but rewardsForA > 0, so a second call would NOT revert (it would try to withdraw again, triggering reentrancy again).
        // Actually, with the bug, claimedBonus is true, so the require in getFirstWithdrawalBonus still fails -> secondCallReverts is true.
        // We need a property that holds for reference but fails for bug.
        // Reference: claimed == true && secondCallReverts == true (always passes).
        // Bug: claimed == true, but because rewardsForA remains non-zero, the balance of the contract is different? Let's check balance.
        // After the attack, the contract's balance in reference should be 1 ether - 100 wei (bonus withdrawn once). In bug, it's 1 ether - 0 wei (bonus never withdrawn).
        // But we need a public surface assertion. We can assert address(c).balance.
        uint256 balanceAfter = address(c).balance;
        // Since we funded with 1 ether and bonus is 100, reference balance should be 1 ether - 100. Bug balance should be 1 ether.
        assertTrue(balanceAfter == 1 ether - 100);
    }
}

